{"filePath":"/testbed/app/cache.py","content":""""Persistent shared JSON cache for public demonstration profiles."""
import json,os,time
from app.config import CACHE_PATH,CACHE_TTL

def _load_entries():
    try:
        with open(CACHE_PATH,'r',encoding='utf-8') as f: data=json.load(f)
        return data if isinstance(data,dict) else {}
    except (OSError,ValueError):
        return {}

def _save_entries(entries):
    directory=os.path.dirname(CACHE_PATH)
    if directory: os.makedirs(directory,exist_ok=True)
    tmp=f'{CACHE_PATH}.{os.getpid()}.tmp'
    with open(tmp,'w',encoding='utf-8') as f: json.dump(entries,f)
    os.replace(tmp,CACHE_PATH)

def get_or_load(key, loader, now=None):
    now=time.time() if now is None else now
    entries=_load_entries()
    entry=entries.get(key)
    if isinstance(entry,dict) and 'value' in entry:
        try: age=now-float(entry.get('stored_at'))
        except (TypeError,ValueError): age=CACHE_TTL
        if age<CACHE_TTL: return entry['value']
    value=loader()
    entries[key]={'stored_at':now,'value':value}
    _save_entries(entries)
    return value
"}

